<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt {{ $sale->receipt_number }}</title><style>body{font:14px Arial;background:#f4f6fa;color:#172b43}.receipt{background:#fff;max-width:650px;margin:30px auto;padding:30px;border:1px solid #ddd}.center{text-align:center}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{text-align:left;padding:9px;border-bottom:1px solid #eee}.right{text-align:right}.actions{max-width:650px;margin:15px auto}button,a{background:#173d65;color:#fff;padding:10px 14px;border:0;border-radius:6px;text-decoration:none;cursor:pointer}@media print{body{background:white}.receipt{border:0;margin:0 auto}.actions{display:none}}</style></head><body><div class="actions"><a href="{{ route('sales.index') }}">Back to Sales</a> <button onclick="window.print()">Print Receipt</button></div><main class="receipt"><div class="center"><h2>{{ $settings['store_name'] ?? 'Italian Shoes' }}</h2><p>{{ $sale->branch->name }}</p><p>{{ $settings['store_address'] ?? $sale->branch->address }}</p><p>{{ $settings['store_phone'] ?? $sale->branch->phone }}</p><h3>SALES RECEIPT</h3></div><p><strong>Receipt:</strong> {{ $sale->receipt_number }}<br><strong>Date:</strong> {{ $sale->sold_at->format('d M Y H:i') }}<br><strong>Cashier:</strong> {{ $sale->cashier->name }}<br><strong>Customer:</strong> {{ $sale->customer?->name ?? 'Walk-in Customer' }}</p><table><tr><th>Item</th><th>Qty</th><th>Price</th><th class="right">Amount</th></tr>@foreach($sale->items as $i)<tr><td>{{ $i->product_name }}<br><small>{{ $i->sku }} · Size {{ $i->size }} · {{ $i->color }}</small></td><td>{{ $i->quantity }}</td><td>{{ number_format($i->unit_price,2) }}</td><td class="right">{{ number_format($i->line_total,2) }}</td></tr>@endforeach</table><table><tr><td>Subtotal</td><td class="right">{{ number_format($sale->subtotal,2) }}</td></tr><tr><td>Discount</td><td class="right">{{ number_format($sale->discount_amount,2) }}</td></tr><tr><td>Tax</td><td class="right">{{ number_format($sale->tax_amount,2) }}</td></tr><tr><th>Total</th><th class="right">PKR {{ number_format($sale->total_amount,2) }}</th></tr><tr><td>Paid</td><td class="right">{{ number_format($sale->amount_paid,2) }}</td></tr><tr><td>Change</td><td class="right">{{ number_format($sale->change_amount,2) }}</td></tr><tr><td>Payment</td><td class="right">{{ strtoupper($sale->payments->first()?->method ?? '') }}</td></tr></table><p class="center">{{ $settings['receipt_footer'] ?? 'Thank you for shopping with Italian Shoes!' }}</p></main></body></html>